head.script:
scwin.CURRENT_PROJECT_ID = "";
scwin.CURRENT_USER_ID = "";
scwin.CURRENT_USER_GROUP_ID = "";

/**
 * 페이지 로드 시 사용자 정보 초기화
 */
scwin.onpageload = function() {
    // 초기화
    scwin.initializeData();

    // 사용자 정보 가져오기
    scwin.getCurrentUserInfo();

    // 부모 창에서 프로젝트 ID 가져오기
    scwin.getProjectIdFromParent();

    // 권한에 따른 UI 조정
    setTimeout(function() {
        scwin.adjustUIByPermission();
    }, 200);

    scwin.handleTaskIdParam();

    console.log("페이지 로드 완료");
};

scwin.handleTaskIdFromDevelop = function(taskId, taskName) {
    console.log("개발업무에서 넘어온 업무 ID:", taskId, taskName);

    // 해당 업무의 테스트 목록 필터링해서 보여주기
    dmp_search.set("searchTaskId", taskId);
    scwin.searchUnitTests();

    // 사용자에게 선택권 제공
    var message = `업무: ${taskName}\n업무ID: ${taskId}\n\n이 업무의 테스트 목록을 확인하고 있습니다.\n새로운 테스트를 등록하시겠습니까?`;

    setTimeout(function() {
        var promise = $c.win.confirm(message);
        promise.then(function(result) {
            if (result) {
                scwin.openTestRegisterWithTask(taskId, taskName);
            }
        });
    }, 500); // 목록 조회 후 확인창 표시
};

// DevelopList에서 업무ID 클릭 시 → 테스트 조회 팝업
scwin.openTestViewPopupWithTask = function(taskId, taskName) {
    console.log("업무별 테스트 조회 팝업 열기:", taskId, taskName);

    // 해당 업무의 테스트 목록 필터링
    dmp_search.set("searchTaskId", taskId);

    // 먼저 데이터 조회
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    // 조회 완료 후 팝업 표시
    setTimeout(function() {
        scwin.showTestListViewPopup(taskId, taskName);
    }, 500);
};

scwin.showTestListViewPopup = function(taskId, taskName) {
    console.log(`업무 ${taskName} (${taskId})의 테스트 조회`);

    // 검색 조건에 해당 업무ID 설정하고 조회
    dmp_search.set("searchTaskId", taskId);

    // 기존 검색 함수 호출
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    // 조회 완료 후 결과에 따라 처리
    setTimeout(function() {
        var successCount = dlt_successList.getTotalRow();
        var failCount = dlt_failList.getTotalRow();
        var totalCount = successCount + failCount;

        if (totalCount == 0) {
            var promise = $c.win.confirm(`업무 "${taskName}"에 등록된 테스트가 없습니다.\n\n새로운 테스트를 등록하시겠습니까?`);
            promise.then(function(result) {
                if (result) {
                    scwin.openTestRegisterPopupWithTask(taskId, taskName);
                }
            });
        }
    }, 500);
};

scwin.openTestViewOnlyPopup = function(taskId, taskName, testList) {
    console.log("테스트 조회 전용 팝업 열기:", taskId, taskName, testList);

    // 임시 데이터에 필터링된 테스트 목록 저장
    scwin.tempFilteredTests = testList;
    scwin.tempTaskInfo = { taskId: taskId, taskName: taskName };

    // 기존 팝업을 조회 모드로 설정하고 첫 번째 테스트 표시
    if (testList.length > 0) {
        dmp_unitTestDetail.setJSON(testList[0]);
        scwin.setFormMode("view");
        pop_overlay.show();

        setTimeout(function() {
            try {
                spn_popupTitle.setValue(`업무: ${taskName} - 테스트 목록 조회 (${testList.length}개)`);

                // // 팝업에 이전/다음 버튼 추가 (있다면)
                // scwin.addNavigationButtons();
            } catch(e) {
                setTimeout(function() {
                    spn_popupTitle.setValue(`업무: ${taskName} - 테스트 목록 조회 (${testList.length}개)`);
                }, 50);
            }
        }, 50);

        // 파일 목록 로드
        scwin.loadFileList();
    }
};


scwin.handleTaskIdParam = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID :", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 flag :", developParam.openRegisterPopup);

            if(developParam.openRegisterPopup) { 
                // DevelopPopup.xml에서 등록 버튼을 누른 경우 → 테스트 등록 팝업
                scwin.openTestRegisterPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
            else { 
                // DevelopList.xml에서 업무ID를 클릭한 경우 → 테스트 조회 팝업
                scwin.openTestViewPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
    }
};


/**
 * 개발업무에서 전달받은 업무ID로 테스트 등록 팝업 열기
 */
scwin.openTestRegisterPopupWithTask = function(taskId, taskName) {
    console.log("개발업무 연동 테스트 등록 팝업 열기:", taskId, taskName);

    // 데이터 완전 초기화
    dmp_unitTestDetail.setEmptyValue();

    // 전달받은 업무 정보로 설정
    dmp_unitTestDetail.set("testCaseId", "");
    dmp_unitTestDetail.set("testStatus", "SUC");
    dmp_unitTestDetail.set("priority", "MEDIUM");
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("taskId", taskId);
    dmp_unitTestDetail.set("taskName", taskName);
    dmp_unitTestDetail.set("assignee", scwin.CURRENT_USER_ID);
    dmp_unitTestDetail.set("assigneeName", scwin.getCurrentUserName() || "현재 사용자");

    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        dmp_unitTestDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);
    }

    // 파일 관련 초기화
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);

    scwin.setFormMode("new");
    pop_overlay.show();

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("새 단위테스트 케이스 등록 (업무: " + taskName + ")");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("새 단위테스트 케이스 등록 (업무: " + taskName + ")");
            }, 50);
        }
    }, 50);

    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();

    console.log("개발업무 연동 테스트 등록 모드로 초기화 완료");
};


/**
 * 데이터 필터링 (권한 적용)
 */
// scwin.filterDataByPermission = function(data) {
