/**
 * 상세보기 팝업 표시
 */
scwin.showDetailPopup = function(mode) {
    console.log("상세보기 팝업 표시:", mode);

    var selectedData = dmp_unitTestDetail.getJSON();

    // 수정 모드일 때 권한 확인
    if (mode === "edit" && !scwin.checkEditPermission(selectedData)) {
        $c.win.alert("본인이 담당한 테스트만 수정할 수 있습니다.");
        return;
    }

    // 팝업 표시
    pop_overlay.show();

    // 모드 설정
    scwin.setFormMode(mode);

    // 제목 설정
    setTimeout(function() {
        try {
            var title = mode === "view" ? "단위테스트 케이스 상세정보" : "단위테스트 케이스 수정";
