/**
 * 폼 모드 설정
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    try {
        if (mode === "edit") {
            // 수정 모드
            scwin.setFieldsReadOnly(false);
            scwin.setEditorMode(true);
            scwin.showFileUploadSection(true);

            // 버튼 상태 변경
            var saveBtn = $p.getComponentById("btn_save");
            var editBtn = $p.getComponentById("btn_popup_edit");

            if (saveBtn && saveBtn.show) saveBtn.show();
            if (editBtn && editBtn.hide) editBtn.hide();

        } else if (mode === "view") {
            // 조회 모드
            scwin.setFieldsReadOnly(true);
            scwin.setEditorMode(false);
            scwin.showFileUploadSection(false);

            // 버튼 상태 변경
            var saveBtn = $p.getComponentById("btn_save");
            var editBtn = $p.getComponentById("btn_popup_edit");
            var deleteBtn = $p.getComponentById("btn_popup_delete");

            if (saveBtn && saveBtn.hide) saveBtn.hide();
            if (editBtn && editBtn.show) editBtn.show();
            if (deleteBtn && deleteBtn.show) deleteBtn.show();

        } else if (mode === "new") {
            // 등록 모드
            scwin.setFieldsReadOnly(false);
            scwin.setEditorMode(true);
            scwin.showFileUploadSection(true);

            // 버튼 상태 변경
            var saveBtn = $p.getComponentById("btn_save");
            var editBtn = $p.getComponentById("btn_popup_edit");
            var deleteBtn = $p.getComponentById("btn_popup_delete");

            if (saveBtn && saveBtn.show) saveBtn.show();
            if (editBtn && editBtn.hide) editBtn.hide();
            if (deleteBtn && deleteBtn.hide) deleteBtn.hide();
        }
    } catch (e) {
        console.error("setFormMode 오류:", e);
        // 오류가 발생해도 계속 진행
    }
};

/**
 * 필드 읽기 전용 설정
 */
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        var editableFields = [
            "inp_testCaseName",
            "inp_testTarget",
            "sel_testType",
            "sel_priority",
            "inp_duration"
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 업무명과 담당자명은 항상 readOnly (선택 버튼으로만 변경 가능)
        var alwaysReadOnlyFields = ["inp_taskName", "inp_assignee"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 에디터 모드 설정
 */
scwin.setEditorMode = function(isEditMode) {
    console.log("에디터 모드 전환:", isEditMode ? "편집" : "조회");

    if (isEditMode) {
        // 편집 모드: 에디터 표시
        grp_description_edit.show();
        grp_description_view.hide();
        grp_testData_edit.show();
        grp_testData_view.hide();
    } else {
        // 조회 모드: 읽기 전용 표시
        grp_description_edit.hide();
        grp_description_view.show();
        grp_testData_edit.hide();
        grp_testData_view.show();

        // 내용 업데이트
        scwin.updateViewContent();
    }
};

/**
 * 파일 업로드 섹션 표시
 */
scwin.showFileUploadSection = function(show) {
    try {
        if (show) {
            grp_fileUploadArea.show();
        } else {
            grp_fileUploadArea.hide();
        }
    } catch(e) {
        console.error("파일 업로드 섹션 표시 오류:", e);
    }
};

/**
 * 조회 모드 내용 업데이트
 */
scwin.updateViewContent = function() {
    try {
        var description = dmp_unitTestDetail.get("description") || "";
        var testData = dmp_unitTestDetail.get("testData") || "";

        // HTML 태그 제거
        txt_description_view.setValue(scwin.stripHtmlTags(description));
        txt_testData_view.setValue(scwin.stripHtmlTags(testData));

    } catch(e) {
        console.error("내용 업데이트 실패:", e);
    }
};

/**
 * HTML 태그 제거
 */
scwin.stripHtmlTags = function(htmlString) {
    if (!htmlString) return "";

    var text = htmlString.replace(/<[^>]*>/g, "");
    text = text.replace(/&nbsp;/g, " ");
    text = text.replace(/&lt;/g, "<");
    text = text.replace(/&gt;/g, ">");
    text = text.replace(/&amp;/g, "&");
    text = text.replace(/&quot;/g, '"');
    text = text.replace(/\s+/g, " ").trim();

    return text;
};

/**
 * 테스트 상태 포맷터
 */
scwin.testStatusCodeFmt = function(data, formattedData, rowIndex, colIndex) {
    if (!data) return "";

    var statusClass = data.trim();
    var statusText = "";

    switch(statusClass) {
        case "SUC": statusText = "성공"; break;
        case "FAI": statusText = "실패"; break;
        default: statusText = statusClass;
    }

    return `<span class="test-status-tag ${statusClass}">${statusText}</span>`;
};

/**
 * 파일 관련 기능들
 */

/**
 * 파일 선택 완료 콜백
 */
scwin.multiUploadSelectDone = function() {
    console.log("=== 파일 선택 완료 콜백 실행 ===");

    // 파일 정보 확인
    var fileInfos = mpd_html5Type.getFileInfos();
    console.log("getFileInfos() 결과:", fileInfos);

    // fileArray도 확인
    if (mpd_html5Type.fileArray) {
        console.log("fileArray:", mpd_html5Type.fileArray);
        console.log("fileArray 길이:", mpd_html5Type.fileArray.length);

        // 각 파일 아이템 상세 확인
        for (var i = 0; i < mpd_html5Type.fileArray.length; i++) {
            var fileItem = mpd_html5Type.fileArray[i];
            console.log("파일 아이템 " + i + ":", fileItem);

            // File 객체 확인
            var actualFile = fileItem.file || fileItem;
            if (actualFile instanceof File) {
                console.log("  - 실제 File 객체:", actualFile.name, actualFile.size);
            } else {
                console.log("  - File 객체가 아님:", typeof actualFile, actualFile);
            }
        }
    }

    var newFileData = [];

    // fileInfos 기준으로 그리드 표시용 데이터 생성
    if (fileInfos && fileInfos.length > 0) {
        for (var i = 0; i < fileInfos.length; i++) {
            var file = fileInfos[i];
            console.log("파일 정보 " + i + ":", file);

            newFileData.push({
                originalFileName: file.name,
                fileSize: file.size,
                fileExtension: scwin.getFileExtension(file.name),
                status: "업로드 대기"
            });
        }
    }

    dlt_upload.setJSON(newFileData);

    try {
        grd_uploadList.refresh();
    } catch(e) {
        console.log("그리드 새로고침 실패, 무시");
    }

    console.log("업로드 대기 파일 수:", newFileData.length);
    console.log("=== 파일 선택 완료 콜백 종료 ===");
};

/**
 * 파일 확장자 추출
 */
scwin.getFileExtension = function(fileName) {
    if (!fileName || fileName.indexOf('.') === -1) return '';
    return fileName.split('.').pop().toLowerCase();
};

/**
 * 파일 목록 로드
 */
scwin.loadFileList = function() {
    console.log("=== 파일 목록 로드 시작 ===");

    var testCaseId = dmp_unitTestDetail.get("testCaseId");
    console.log("테스트 케이스 ID:", testCaseId);

    if (!testCaseId || testCaseId.trim() === "") {
        console.log("테스트 케이스 ID가 없습니다. 파일 목록을 초기화합니다.");
        dlt_attVoList.setJSON([]);
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        return;
    }

    // 이슈리스크와 동일한 방식으로 데이터 설정
    console.log("파일 목록 조회 요청 - testCaseId:", testCaseId);

    // submission 실행
    $c.sbm.execute($p, sbm_selectUnitTestFileList);
};

/**
 * 파일 목록 조회 완료
 */
scwin.sbm_selectUnitTestFileList_submitdone = function(e) {
    console.log("=== 파일 목록 조회 응답 처리 시작 ===");

    // 응답 전체 구조 로깅
    console.log("전체 응답 객체:", e);
    console.log("responseJSON:", e.responseJSON);

    try {
        var responseData = e.responseJSON;

        // 응답 구조 상세 분석
        if (responseData) {
            console.log("응답 구조 분석:");
            console.log("- elHeader:", responseData.elHeader);
            console.log("- elData:", responseData.elData);

            if (responseData.elData) {
                console.log("- elData.attVoList:", responseData.elData.attVoList);
                console.log("- attVoList 타입:", typeof responseData.elData.attVoList);
                console.log("- attVoList 길이:", responseData.elData.attVoList ? responseData.elData.attVoList.length : "undefined");
            }
        }

        var elData = responseData ? responseData.elData : null;
        var elHeader = responseData ? responseData.elHeader : null;

        // 헤더 확인
        if (elHeader) {
            console.log("elHeader.resSuc:", elHeader.resSuc);
            console.log("elHeader.resCode:", elHeader.resCode);
            console.log("elHeader.resMsg:", elHeader.resMsg);
        }

        // 성공 여부 확인
        if (!elHeader || elHeader.resSuc !== true) {
            var errorMsg = "파일 목록 조회에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            console.error("응답 실패:", errorMsg);

            // 실패해도 빈 배열로 설정
            dlt_attVoList.setJSON([]);
            return;
        }

        // 파일 목록 데이터 처리
        var fileList = [];
        if (elData && elData.attVoList) {
            fileList = elData.attVoList;
            console.log("파일 목록 데이터:", fileList);
        } else {
            console.warn("attVoList가 응답에 없습니다.");
        }

        // 그리드에 데이터 설정
        console.log("그리드에 설정할 파일 개수:", fileList.length);
        dlt_attVoList.setJSON(fileList);

        // 그리드 데이터 확인
        console.log("그리드 설정 후 총 행 수:", dlt_attVoList.getTotalRow());

        // 미리보기 초기화
        if (fileList.length === 0) {
            scwin.hideAllPreviewPanels();
            scwin.showNoPreview();
        }

        console.log("=== 파일 목록 조회 응답 처리 완료 ===");

    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        dlt_attVoList.setJSON([]);
    }
};

/**
 * 파일 목록 조회 실패 콜백
 */
scwin.sbm_selectUnitTestFileList_submiterror = function(e) {
    console.error("파일 목록 조회 실패:", e);
    scwin.handleError("파일 목록 조회", e, false);
    dlt_attVoList.setJSON([]);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 파일 그리드 셀 클릭 (미리보기)
 */
scwin.grd_fileList_oncellclick = function(row, col, colId) {
    console.log("파일 그리드 셀 클릭:", row, colId);

    var rowData = dlt_attVoList.getRowJSON(row);

    if (colId === "originalFileName") {
        scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
    }
};

/**
 * 파일 그리드 액션 버튼 클릭
 */
scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_attVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    console.log("파일 정보:", fileId, fileName);

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    // 다운로드 버튼 클릭 감지
    if (targetId && (targetId.indexOf("download") >= 0 || targetId.indexOf("다운로드") >= 0)) {
        // 먼저 기본 방법 시도, 실패시 대안 방법 시도
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    } else if (col === 3) { // 3번째 컬럼 (작업 컬럼)
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    } else if (targetId && (targetId.indexOf("delete") >= 0 || targetId.indexOf("삭제") >= 0)) {
        scwin.deleteFile(fileId);
    } else {
        // 기본적으로 다운로드
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    }
};

/**
 * 파일 미리보기
 */
scwin.previewFile = function(fileId, fileName, fileExtension) {
    console.log("파일 미리보기:", fileName, fileExtension);

    dmp_currentFile.set("fileId", fileId);
    dmp_currentFile.set("originalFileName", fileName);
    dmp_currentFile.set("fileExtension", fileExtension);

    scwin.hideAllPreviewPanels();

    var ext = fileExtension ? fileExtension.toLowerCase() : "";

    if (scwin.isImageFile(ext)) {
        scwin.showImagePreview(fileId, fileName);
    } else if (scwin.isTextFile(ext)) {
        scwin.showTextPreview(fileId, fileName);
    } else if (scwin.isDocumentFile(ext)) {
        scwin.showDocumentPreview(fileId, fileName, ext);
    } else {
        scwin.showUnsupportedPreview(fileName);
    }
};

/**
 * 파일 타입 체크
 */
scwin.isImageFile = function(ext) {
    var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'];
    return imageExts.indexOf(ext) !== -1;
};

scwin.isTextFile = function(ext) {
    var textExts = ['txt', 'log', 'csv', 'json', 'xml', 'html', 'css', 'js', 'java', 'sql', 'properties'];
    return textExts.indexOf(ext) !== -1;
};

scwin.isDocumentFile = function(ext) {
    var docExts = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp'];
    return docExts.indexOf(ext) !== -1;
};

/**
 * 미리보기 패널 제어
 */
scwin.hideAllPreviewPanels = function() {
    try {
        grp_noPreview.hide();
        grp_imagePreview.hide();
        grp_textPreview.hide();
        grp_documentPreview.hide();
    } catch(e) {
        console.error("미리보기 패널 숨기기 오류:", e);
    }
};

scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.error("기본 미리보기 표시 오류:", e);
    }
};

scwin.showImagePreview = function(fileId, fileName) {
    console.log("이미지 미리보기:", fileName);

    var imageUrl = "/InsWebApp/ImagePreview.pwkjson?fileId=" + fileId;

    try {
        txt_previewFileName.setValue(fileName);
        grp_imagePreview.show();

        setTimeout(function() {
            var imgElement = document.getElementById("img_preview");
            if (imgElement) {
                imgElement.src = imageUrl;
                imgElement.style.width = "150px";
                imgElement.style.height = "150px";
                imgElement.style.objectFit = "cover";
                imgElement.style.border = "1px solid #ddd";
                imgElement.style.background = "white";
                imgElement.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
                imgElement.style.borderRadius = "4px";

                imgElement.onerror = function() {
                    console.error("이미지 로드 실패:", imageUrl);
                    scwin.showUnsupportedPreview(fileName, "이미지를 로드할 수 없습니다.");
                };
            }
        }, 100);
    } catch(e) {
        console.error("이미지 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showTextPreview = function(fileId, fileName) {
    console.log("텍스트 미리보기:", fileName);

    try {
        txt_textFileName.setValue(fileName);
        grp_textPreview.show();

        fetch("/InsWebApp/FilePreview.pwkjson?fileId=" + fileId)
            .then(function(response) { return response.text(); })
            .then(function(text) {
                if (text.length > 5000) {
                    text = text.substring(0, 5000) + "\n\n... (파일 내용이 길어서 일부만 표시됩니다)";
                }
                txt_textContent.setValue(text);
            })
            .catch(function(error) {
                console.error("텍스트 파일 로드 실패:", error);
                txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다.");
            });
    } catch(e) {
        console.error("텍스트 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showDocumentPreview = function(fileId, fileName, ext) {
    console.log("문서 미리보기:", fileName, ext);

    try {
        txt_documentFileName.setValue(fileName);

        var fileInfo = "";
        switch(ext) {
            case 'pdf': fileInfo = "PDF 문서 파일입니다."; break;
            case 'doc':
            case 'docx': fileInfo = "Microsoft Word 문서입니다."; break;
            case 'xls':
            case 'xlsx': fileInfo = "Microsoft Excel 스프레드시트입니다."; break;
            case 'ppt':
            case 'pptx': fileInfo = "Microsoft PowerPoint 프레젠테이션입니다."; break;
            case 'hwp': fileInfo = "한글 문서 파일입니다."; break;
            default: fileInfo = "문서 파일입니다.";
        }

        txt_documentInfo.setValue(fileInfo);
        grp_documentPreview.show();
    } catch(e) {
        console.error("문서 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showUnsupportedPreview = function(fileName, message) {
    console.log("지원하지 않는 파일 미리보기:", fileName);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 현재 미리보기 파일 다운로드
 */
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

/**
 * 파일 다운로드
 */
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        // 프로웍스 표준에 맞게 .pwkjson 확장자 사용
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        console.log("다운로드 URL:", downloadUrl);

        // iframe을 사용한 다운로드 (프로웍스 표준 방식)
        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.style.position = 'absolute';
        iframe.style.left = '-9999px';
        iframe.src = downloadUrl;

        document.body.appendChild(iframe);

        // 다운로드 완료 후 iframe 제거
        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};


/**
 * 파일 삭제
 */
scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            dmp_currentFile.set("fileId", fileId);
            $c.sbm.execute($p, sbm_deleteUnitTestFile);
        }
    });
};

scwin.sbm_deleteUnitTestFile_submit = function(e) {
    var fileId = dmp_currentFile.get("fileId");
    if (!fileId) {
        console.error("삭제할 파일 ID가 없습니다.");
        return;
    }

    // URL에 파라미터 추가
    var deleteUrl = "/InsWebApp/UNIT001FileDelete.pwkjson?fileId=" + encodeURIComponent(fileId);
    sbm_deleteUnitTestFile.setAction(deleteUrl);

    // 빈 데이터로 전송
    sbm_deleteUnitTestFile.setRequestData("");
};

/**
 * 파일 삭제 완료
 */
scwin.sbm_deleteUnitTestFile_submitdone = function(e) {
    console.log("파일 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
        return;
    }

    alert("파일이 삭제되었습니다.");

    // 현재 미리보기 중인 파일이 삭제된 경우 초기화
    var deletedFileId = dmp_currentFile.get("fileId");
    if (deletedFileId) {
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        dmp_currentFile.setEmptyValue();
    }

    // 파일 목록 새로고침
    scwin.loadFileList();
};

/**
 * 파일 업로드 초기화
 */
scwin.btn_InitMultiupload_onclick = function(e) {
    console.log("파일 업로드 초기화");

    dlt_upload.setJSON([]);

    if (mpd_html5Type) {
        if (mpd_html5Type.clear) {
            mpd_html5Type.clear();
        } else if (mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        } else if (mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray = [];
        }
    }

    console.log("파일 업로드 초기화 완료");
};

/**
 * 업로드 파일 삭제
 */
scwin.removeUploadFile = function(row, col, colId, targetId) {
    console.log("업로드 파일 삭제:", row);

    try {
        dlt_upload.removeRow(row);

        if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
            mpd_html5Type.removeFileByIndex(row);
        } else if (mpd_html5Type && mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray.splice(row, 1);
        }

        try {
            grd_uploadList.refresh();
        } catch(e) {
            console.log("그리드 새로고침 실패, 무시");
        }

    } catch(error) {
        console.error("파일 삭제 중 오류:", error);
        alert("파일 삭제 중 오류가 발생했습니다.");
    }
};

/**
 * 테스트 상태 업데이트
 */
scwin.updateTestStatus = function(testCaseId, newStatus) {
    console.log("테스트 상태 업데이트:", testCaseId, newStatus);

    dmp_unitTestDetail.set("testCaseId", testCaseId);
    dmp_unitTestDetail.set("testStatus", newStatus);

    $c.sbm.execute($p, sbm_updateTestStatus);
};

/**
 * 테스트 상태 업데이트 완료
 */
scwin.sbm_updateTestStatus_submitdone = function(e) {
    console.log("테스트 상태 업데이트 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`상태 업데이트 실패: ${elHeader ? elHeader.resMsg : "알 수 없는 오류"}`);
        return;
    }

    $c.win.alert("상태가 업데이트되었습니다.");

    // 프로젝트가 선택되어 있으면 프로젝트별 조회, 아니면 일반 조회
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }
};

/**
 * 프로젝트 변경 시 호출되는 함수 (부모 창에서 호출)
 */
scwin.onProjectChange = function(projectId) {
    console.log("프로젝트 변경 이벤트 수신:", projectId);

    scwin.CURRENT_PROJECT_ID = projectId;

    // 사용자 정보 다시 가져오기 (새로운 프로젝트의 그룹 정보로 업데이트)
    scwin.getCurrentUserInfo();

    console.log("프로젝트 변경 후 권한 정보:", {
        프로젝트ID: scwin.CURRENT_PROJECT_ID,
        사용자ID: scwin.CURRENT_USER_ID,
        그룹ID: scwin.CURRENT_USER_GROUP_ID,
        PM여부: scwin.isPM()
    });

    // 권한에 따른 UI 재조정
    scwin.adjustUIByPermission();

    if (projectId && projectId !== "") {
        // 프로젝트가 선택되면 해당 프로젝트의 테스트 조회
        scwin.searchUnitTestsByProject();
        scwin.loadStatisticsByProject();
    } else {
        // 프로젝트가 선택 해제되면 일반 조회
        scwin.searchUnitTests();
        scwin.loadStatistics();
    }
};

