scwin.btn_excel_combined_download_onclick = function (e) {
    var successData = scwin.successPageInfo.data || [];
    var failData = scwin.failPageInfo.data || [];

    if (successData.length === 0 && failData.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    console.log("통합 엑셀 다운로드:", successData.length, "개 성공,", failData.length, "개 실패");

    // 성공 데이터 다운로드
    if (successData.length > 0) {
        var originalSuccessData = dlt_successList.getAllJSON();
        dlt_successList.setJSON(successData);

        var successOptions = {
            fileName: "단위테스트_성공실패_통합_" + new Date().toISOString().slice(0, 10).replace(/-/g, "") + "_성공시트",
            sheetName: "성공한_테스트", 
            useStyle: true,
            headerFontBold: true,
            bodyFontBold: false,
            type: 1,
            trim: 1,
            processMsg: "성공 데이터 엑셀 파일을 생성하고 있습니다...",
            timeout: 60000,
            checkInterval: 1000,
            onSuccessCallback: function () {
                dlt_successList.setJSON(originalSuccessData);

                // 성공 다운로드 완료 후 실패 데이터 다운로드
                if (failData.length > 0) {
                    setTimeout(function() {
                        scwin.downloadFailDataAfterSuccess();
                    }, 1000);
                } else {
                    $c.win.alert("성공 테스트 엑셀 파일 다운로드가 완료되었습니다.");
                }
            },
            onFailureCallback: function () {
                dlt_successList.setJSON(originalSuccessData);
                $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            }
        };

        success_grd.advancedExcelDownload(successOptions);
    } else if (failData.length > 0) {
        // 성공 데이터가 없으면 바로 실패 데이터 다운로드
        scwin.downloadFailDataAfterSuccess();
    }
};

scwin.downloadFailDataAfterSuccess = function() {
    var failData = scwin.failPageInfo.data || [];
    var originalFailData = dlt_failList.getAllJSON();
    dlt_failList.setJSON(failData);

    var failOptions = {
        fileName: "단위테스트_성공실패_통합_" + new Date().toISOString().slice(0, 10).replace(/-/g, "") + "_실패시트",
        sheetName: "실패한_테스트",
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1,
        trim: 1,
        processMsg: "실패 데이터 엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            dlt_failList.setJSON(originalFailData);
            $c.win.alert("성공/실패 통합 엑셀 파일 다운로드가 완료되었습니다.");
        },
        onFailureCallback: function () {
            dlt_failList.setJSON(originalFailData);
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
        }
    };

    fail_grd.advancedExcelDownload(failOptions);
};


/**
 * CSV 다운로드 (템플릿 불필요)
 */
scwin.btn_csv_download_onclick = function(e) {
    var allData = scwin.allDataPageInfo.data || [];

    if (allData.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // CSV 헤더
    var csvContent = "테스트ID,업무명,테스트케이스명,테스트대상,테스트타입,우선순위,상태,담당자,실행일시,소요시간,등록일시\n";

    // CSV 데이터 생성
    allData.forEach(function(item) {
        var row = [
            item.testCaseId || "",
            item.taskName || "",
            item.testCaseName || "",
            item.testTarget || "",
            scwin.getTestTypeName(item.testType) || "",
            scwin.getPriorityName(item.priority) || "",
            item.testStatus === "SUC" ? "성공" : "실패",
            item.assignee || "",
            item.executionDate || "",
            item.duration || "",
            item.createdAt || ""
        ].map(function(field) {
            // CSV 특수문자 처리
            return '"' + String(field).replace(/"/g, '""') + '"';
        });
        csvContent += row.join(",") + "\n";
    });

    // 파일 다운로드
    var blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    var link = document.createElement("a");
    var url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", "단위테스트_목록_" + new Date().toISOString().slice(0, 10) + ".csv");
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    $c.win.alert("CSV 파일 다운로드가 완료되었습니다.");
};

scwin.btn_basic_excel_download_onclick = function(e) {
