/**
 * JSON 다운로드
 */
scwin.btn_json_download_onclick = function(e) {
    var allData = scwin.allDataPageInfo.data || [];

    if (allData.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // JSON 데이터 정리
    var jsonData = allData.map(function(item) {
        return {
            testCaseId: item.testCaseId,
            taskName: item.taskName,
            testCaseName: item.testCaseName,
            testTarget: item.testTarget,
            testType: item.testType,
            testTypeName: scwin.getTestTypeName(item.testType),
            priority: item.priority,
            priorityName: scwin.getPriorityName(item.priority),
            testStatus: item.testStatus,
            testStatusName: item.testStatus === "SUC" ? "성공" : "실패",
            assignee: item.assignee,
            executionDate: item.executionDate,
            duration: item.duration,
            description: item.description,
            testData: item.testData,
            createdAt: item.createdAt
        };
    });

    var jsonContent = JSON.stringify(jsonData, null, 2);

    // 파일 다운로드
    var blob = new Blob([jsonContent], { type: 'application/json;charset=utf-8;' });
    var link = document.createElement("a");
    var url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", "단위테스트_목록_" + new Date().toISOString().slice(0, 10) + ".json");
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    $c.win.alert("JSON 파일 다운로드가 완료되었습니다.");
};

scwin.btn_excel_download_onclick = function (e) {
    var totalCount = scwin.globalElData ? scwin.globalElData.totalCount : 0;
    console.log("전체 데이터 건수:", totalCount);

    if (totalCount === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    var originalPageIndex = dmp_search.get("pageIndex");
    var originalPageSize = dmp_search.get("pageSize");

    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", totalCount.toString());

    $c.sbm.execute($p, sbm_selectUnitTestListForExcel);

    dmp_search.set("pageIndex", originalPageIndex);
    dmp_search.set("pageSize", originalPageSize);
};

scwin.sbm_selectUnitTestListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    if (!elData.unitTestList || elData.unitTestList.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    var processedData = elData.unitTestList.map(function(item) {
        return {
            testCaseId: item.testCaseId,
            taskId: item.taskId,
            taskName: item.taskName,
            testCaseName: item.testCaseName,
            testTarget: item.testTarget,
            testType: item.testType,
            priority: item.priority,
            description: item.description,
            testData: item.testData,
            testStatus: item.testStatus,
            executionDate: item.executionDate,
            duration: item.duration,
            assignee: item.assignee,
            createdAt: item.createdAt,
            updatedAt: item.updatedAt,
            testTypeName: scwin.getTestTypeName(item.testType),
            priorityName: scwin.getPriorityName(item.priority),
            testStatusName: item.testStatus === "SUC" ? "성공" : "실패"
        };
    });

    var originalData = dlt_unitTestVoList.getAllJSON();
    dlt_unitTestVoList.setJSON(processedData);

    var options = {
        fileName: "단위테스트_케이스_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1, 
        trim: 1,
        removeColumns: "7,8",
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            $c.win.alert("엑셀 파일 다운로드가 완료되었습니다.");
            dlt_unitTestVoList.setJSON(originalData);
        },
        onFailureCallback: function () {
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            dlt_unitTestVoList.setJSON(originalData);
        }
    };

    grd_list.advancedExcelDownload(options);
};

